function download(url) {
  return new Promise((resolve, reject) => {
    const client = url.startsWith('https:') ? https : http;
    client.get(url, response => {
      if (response.statusCode >= 300 && response.statusCode < 400 && response.headers.location) {
        response.resume();
        resolve(download(new URL(response.headers.location, url).href));
        return;
      }
      if (response.statusCode !== 200) {
        response.resume();
        reject(new Error(`Unable to load transform ${url}: HTTP ${response.statusCode}`));
        return;
      }
      const chunks = [];
      response.on('data', chunk => chunks.push(chunk));
      response.on('end', () => {
        const directory = fs.mkdtempSync(path.join(os.tmpdir(), 'jscodeshift-'));
        const extension = path.extname(new URL(url).pathname);
        const filename = path.join(directory, `transform${extension}`);
        fs.writeFileSync(filename, Buffer.concat(chunks));
        resolve({filename, directory});
      });
    }).on('error', reject);
  });
}

async function main() {
  const input = fs.readFileSync(0, 'utf8');
  const request = JSON.parse(input);
  let transform = request.transform;
  let temporaryDirectory;

  if (/^https?:/.test(transform)) {
    const downloaded = await download(transform);
    transform = downloaded.filename;
    temporaryDirectory = downloaded.directory;
  }

  const createWorker = require('../src/Worker');
  const worker = createWorker([transform, request.babel === false ? 'no-babel' : 'babel']);
  worker.on('message', message => send({kind: 'event', message}));
  worker.on('disconnect', () => {
    if (temporaryDirectory) {
      fs.rmSync(temporaryDirectory, {recursive: true, force: true});
    }
    send({kind: 'complete'});
  });
  worker.send({files: request.files, options: request.options});
}

main().catch(error => {
  send({kind: 'error', message: error.message, stack: error.stack});
  process.exitCode = 1;
});
