                                (default: false)
  -h, --help                    print this help and exit
      --ignore-config=FILE ...  ignore files if they match patterns sourced from a configuration file (e.g. a .gitignore)
      --ignore-pattern=GLOB ...  ignore files that match a provided glob expression
      --(no-)gitignore          adds entries the current directory's .gitignore file
                                (default: false)
      --parser=babel|babylon|flow|ts|tsx  the parser to use for parsing the source files
                                          (default: babel)
      --parser-config=FILE      path to a JSON file containing a custom parser configuration for flow or babylon
  -p, --(no-)print              print transformed files to stdout, useful for development
                                (default: false)
      --(no-)run-in-band        run serially in the current process
                                (default: false)
  -s, --(no-)silent             do not write to stdout or stderr
                                (default: false)
      --(no-)stdin              read file/directory list from stdin
                                (default: false)
  -t, --transform=FILE          path to the transform file. Can be either a local path or url
                                (default: ./transform.js)
  -v, --verbose=0|1|2           show more information about the transform process
                                (default: 0)
      --version                 print version and exit
"#;

#[derive(Clone)]
enum Value {
    Bool(bool),
    Number(i64),
    String(String),
    Json(String),
    List(Vec<Value>),
}

impl Value {
    fn json(&self) -> String {
        match self {
            Value::Bool(value) => value.to_string(),
            Value::Number(value) => value.to_string(),
            Value::String(value) => quote(value),
            Value::Json(value) => value.clone(),
            Value::List(values) => format!("[{}]", values.iter().map(Value::json).collect::<Vec<_>>().join(",")),
        }
    }
}

struct Parsed {
    options: BTreeMap<String, Value>,
    paths: Vec<String>,
}

fn quote(value: &str) -> String {
    let mut out = String::from("\"");
    for character in value.chars() {
        match character {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c.is_control() => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

fn option_key(name: &str) -> Option<(&'static str, bool, bool)> {
    match name {
        "--transform" | "-t" => Some(("transform", false, false)),
        "--cpus" | "-c" => Some(("cpus", false, false)),
        "--verbose" | "-v" => Some(("verbose", false, false)),
        "--dry" | "-d" => Some(("dry", true, false)),
        "--babel" => Some(("babel", true, false)),
        "--extensions" => Some(("extensions", false, false)),
        "--ignore-pattern" => Some(("ignorePattern", false, true)),
        "--ignore-config" => Some(("ignoreConfig", false, true)),
        "--gitignore" => Some(("gitignore", true, false)),
        "--run-in-band" => Some(("runInBand", true, false)),
        "--silent" | "-s" => Some(("silent", true, false)),
        "--parser" => Some(("parser", false, false)),
        "--parser-config" => Some(("parserConfig", false, false)),
        "--fail-on-error" => Some(("failOnError", true, false)),
        "--stdin" => Some(("stdin", true, false)),
        _ => None,
    }
}

fn is_option(value: &str) -> bool {
    value.starts_with('-')
}

fn custom_value(value: String) -> Value {
    let trimmed = value.trim();
    if matches!(trimmed, "true" | "false" | "null") || trimmed.parse::<f64>().is_ok() ||
        ((trimmed.starts_with('{') && trimmed.ends_with('}')) || (trimmed.starts_with('[') && trimmed.ends_with(']')))
    {
        Value::Json(value)
    } else {
        Value::String(value)
    }
}

fn missing_value(name: &str) -> String {
    format!("Missing value: --{} requires a value\n\n---\n\n{}", name, HELP)
}

fn parse_args(args: &[String]) -> Result<Parsed, (i32, String)> {
    let mut options = BTreeMap::new();
    options.insert("babel".into(), Value::Bool(true));
    options.insert("dry".into(), Value::Bool(false));
    options.insert("extensions".into(), Value::String(EXTENSIONS.into()));
    options.insert("failOnError".into(), Value::Bool(false));
    options.insert("gitignore".into(), Value::Bool(false));
    options.insert("ignoreConfig".into(), Value::List(Vec::new()));
    options.insert("ignorePattern".into(), Value::List(Vec::new()));
    options.insert("parser".into(), Value::String("babel".into()));
    options.insert("print".into(), Value::Bool(false));
    options.insert("runInBand".into(), Value::Bool(false));
    options.insert("silent".into(), Value::Bool(false));
    options.insert("stdin".into(), Value::Bool(false));
    options.insert("transform".into(), Value::String("./transform.js".into()));
    options.insert("verbose".into(), Value::Number(0));

    let mut paths = Vec::new();
    let mut index = 0;
    while index < args.len() {
        let argument = &args[index];
        if argument == "--help" || argument == "-h" {
            return Err((0, HELP.into()));
        }
        if argument == "--version" {
            return Err((2, String::new()));
        }
        if !is_option(argument) {
            paths.push(argument.clone());
            index += 1;
            continue;
        }

        let (name, inline) = match argument.split_once('=') {
            Some((name, value)) => (name, Some(value.to_string())),
            None => (argument.as_str(), None),
        };
        let negated = name.starts_with("--no-");
        let normalized = if negated { format!("--{}", &name[5..]) } else { name.to_string() };
        let known = option_key(&normalized);
        let (key, flag, list) = known.unwrap_or_else(|| {
            let key = name.trim_start_matches('-').trim_start_matches("no-").to_string();
            let has_value = inline.is_some() || args.get(index + 1).map(|next| !is_option(next)).unwrap_or(false);
            let is_list = matches!(options.get(&key), Some(Value::String(_)) | Some(Value::Number(_)) | Some(Value::Json(_)) | Some(Value::List(_))) && has_value;
            (Box::leak(key.into_boxed_str()), !options.contains_key(name.trim_start_matches('-')) && !has_value, is_list)
        });

        if flag {
            let value = if negated { false } else { inline.as_deref().map(|v| v == "1").unwrap_or(true) };
            options.insert(key.into(), Value::Bool(value));
        } else {
            let value = match inline {
                Some(value) => value,
                None if index + 1 < args.len() && !is_option(&args[index + 1]) => {
                    index += 1;
                    args[index].clone()
                }
                None => return Err((1, missing_value(key))),
            };
            let parsed = if key == "cpus" || key == "verbose" {
                Value::Number(value.parse().unwrap_or(0))
            } else if key == "parserConfig" {
                match fs::read_to_string(&value) {
                    Ok(contents) => Value::Json(contents),
                    Err(error) => return Err((1, error.to_string())),
                }
            } else if known.is_some() {
                Value::String(value)
            } else {
                custom_value(value)
            };
            if list {
                match options.remove(key) {
                    Some(Value::List(mut values)) => { values.push(parsed); options.insert(key.into(), Value::List(values)); }
                    Some(previous) => options.insert(key.into(), Value::List(vec![previous, parsed])),
                    None => options.insert(key.into(), Value::List(vec![parsed])),
                };
            } else {
                options.insert(key.into(), parsed);
            }
        }
        index += 1;
    }

    let parser = match options.get("parser") { Some(Value::String(value)) => value.as_str(), _ => "babel" };
    if !["babel", "babylon", "flow", "ts", "tsx"].contains(&parser) {
        return Err((1, format!("Error: --parser must be one of the values babel, babylon, flow, ts, tsx\n\n---\n\n{}", HELP)));
    }
    Ok(Parsed {options, paths})
}

fn bool_option(options: &BTreeMap<String, Value>, key: &str) -> bool {
    matches!(options.get(key), Some(Value::Bool(true)))
}

fn number_option(options: &BTreeMap<String, Value>, key: &str) -> i64 {
    match options.get(key) { Some(Value::Number(value)) => *value, _ => 0 }
}

fn string_option(options: &BTreeMap<String, Value>, key: &str) -> String {
    match options.get(key) { Some(Value::String(value)) => value.clone(), _ => String::new() }
}

fn list_option(options: &BTreeMap<String, Value>, key: &str) -> Vec<String> {
    match options.get(key) {
        Some(Value::List(values)) => values.iter().filter_map(|value| match value { Value::String(value) => Some(value.clone()), _ => None }).collect(),
        _ => Vec::new(),
    }
}

fn add_pattern(patterns: &mut Vec<String>, value: &str) {
    if value.is_empty() || value.starts_with('#') { return; }
    if !value.contains('/') { patterns.push(format!("**/{}", value)); }
    else if value.ends_with('/') {
        patterns.push(format!("**/{}**", value));
        patterns.push(format!("{}**", value));
    }
    patterns.push(value.to_string());
}

fn glob_matches(pattern: &[u8], text: &[u8], p: usize, t: usize) -> bool {
    if p == pattern.len() { return t == text.len(); }
    match pattern[p] {
        b'*' if p + 1 < pattern.len() && pattern[p + 1] == b'*' => {
            let mut next = p + 2;
            while next < pattern.len() && pattern[next] == b'*' { next += 1; }
            if next < pattern.len() && pattern[next] == b'/' {
                if glob_matches(pattern, text, next + 1, t) { return true; }
                for end in t..text.len() {
                    if text[end] == b'/' && glob_matches(pattern, text, next + 1, end + 1) { return true; }
                }
                false
            } else {
                (t..=text.len()).any(|end| glob_matches(pattern, text, next, end))
            }
        }
        b'*' => {
            let mut end = t;
            loop {
                if glob_matches(pattern, text, p + 1, end) { return true; }
                if end == text.len() || text[end] == b'/' { return false; }
                end += 1;
            }
        }
        b'?' => t < text.len() && text[t] != b'/' && glob_matches(pattern, text, p + 1, t + 1),
        literal => t < text.len() && literal == text[t] && glob_matches(pattern, text, p + 1, t + 1),
    }
}

fn should_ignore(path: &str, patterns: &[String]) -> bool {
    let normalized = path.trim_start_matches(|character| character == '.' || character == '/' || character == '\\');
    patterns.iter().any(|pattern| glob_matches(pattern.as_bytes(), path.as_bytes(), 0, 0) ||
        (normalized != path && glob_matches(pattern.as_bytes(), normalized.as_bytes(), 0, 0)))
}

fn discover(path: &Path, extensions: &[String], patterns: &[String], files: &mut Vec<String>, nested: bool) {
    let display = path.to_string_lossy().to_string();
    let metadata = match fs::metadata(path) {
        Ok(metadata) => metadata,
        Err(_) if !nested => { eprintln!("Skipping path {} which does not exist. ", display); return; }
        Err(_) => { println!("Skipping path \"{}\" which does not exist.", display); return; }
    };
    if metadata.is_dir() {
        let entries = match fs::read_dir(path) { Ok(entries) => entries, Err(error) => { eprintln!("{}", error); return; } };
        for entry in entries.flatten() {
            let child = entry.path();
            let name = child.to_string_lossy().to_string();
            if should_ignore(&name, patterns) { continue; }
            discover(&child, extensions, patterns, files, true);
        }
    } else if !should_ignore(&display, patterns) && extensions.iter().any(|extension| display.ends_with(extension)) {
        files.push(display);
    }
}

fn root_dir() -> Result<PathBuf, String> {
    let mut candidates = Vec::new();
    if let Ok(root) = env::var("JSCODESHIFT_ROOT") { candidates.push(PathBuf::from(root)); }
    if let Ok(executable) = env::current_exe() {
        candidates.extend(executable.ancestors().map(Path::to_path_buf));
    }
    if let Ok(current) = env::current_dir() {
        candidates.extend(current.ancestors().map(Path::to_path_buf));
    }
    candidates.into_iter().find(|candidate| candidate.join("bridge/transform-host.js").is_file())
        .ok_or_else(|| "Unable to locate the jscodeshift JavaScript compatibility bridge.".into())
}

fn event_file() -> PathBuf {
    let nonce = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_nanos();
    env::temp_dir().join(format!("jscodeshift-rs-{}-{}.events", std::process::id(), nonce))
}

fn decode_base64(value: &str) -> String {
    const TABLE: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut bytes = Vec::new();
    let mut buffer = 0u32;
    let mut bits = 0;
    for character in value.bytes().filter(|character| *character != b'=') {
        let Some(position) = TABLE.iter().position(|item| *item == character) else { return String::new(); };
        buffer = (buffer << 6) | position as u32;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            bytes.push((buffer >> bits) as u8);
            buffer &= (1 << bits) - 1;
        }
    }
    String::from_utf8_lossy(&bytes).into_owned()
}

fn main() {
    let arguments = env::args().skip(1).collect::<Vec<_>>();
    let parsed = match parse_args(&arguments) {
        Ok(parsed) => parsed,
        Err((2, _)) => { print_version(); return; }
        Err((code, message)) => { if code == 0 { print!("{}", message); } else { eprint!("{}", message); } std::process::exit(code); }
    };
    if parsed.paths.is_empty() && !bool_option(&parsed.options, "stdin") {
        eprint!("Error: You have to provide at least one file/directory to transform.\n\n---\n\n{}", HELP);
        std::process::exit(1);
    }

    let transform = string_option(&parsed.options, "transform");
    let transform = if transform.starts_with("http:") || transform.starts_with("https:") {
        transform
    } else {
        match env::current_dir() { Ok(directory) => directory.join(transform).to_string_lossy().into_owned(), Err(_) => transform }
    };
    if !transform.starts_with("http") && !Path::new(&transform).exists() {
        eprintln!("ERROR Transform file {} does not exist ", transform);
        return;
    }

    let mut requested_paths = parsed.paths;
    if bool_option(&parsed.options, "stdin") {
        let mut input = String::new();
        io::stdin().read_to_string(&mut input).unwrap_or_default();
        requested_paths = input.split('\n').map(str::to_string).collect();
    }

    let mut patterns = Vec::new();
    for pattern in list_option(&parsed.options, "ignorePattern") { add_pattern(&mut patterns, &pattern); }
    for config in list_option(&parsed.options, "ignoreConfig") {
        match fs::read_to_string(&config) {
            Ok(contents) => for line in contents.lines() { add_pattern(&mut patterns, line); },
            Err(error) => { eprintln!("{}", error); std::process::exit(1); }
        }
    }
    if bool_option(&parsed.options, "gitignore") {
        if let Ok(contents) = fs::read_to_string(".gitignore") {
            for line in contents.lines() { add_pattern(&mut patterns, line); }
        }
    }

    let extensions = string_option(&parsed.options, "extensions").split(',').map(|extension| format!(".{}", extension)).collect::<Vec<_>>();
    let mut files = Vec::new();
    for path in requested_paths { discover(Path::new(&path), &extensions, &patterns, &mut files, false); }
    if files.is_empty() { println!("No files selected, nothing to do. "); return; }

    let silent = bool_option(&parsed.options, "silent");
    let run_in_band = bool_option(&parsed.options, "runInBand");
    let cpus = std::thread::available_parallelism().map(|count| count.get().saturating_sub(1).max(1)).unwrap_or(1);
    let requested_cpus = number_option(&parsed.options, "cpus");
    let workers = if run_in_band { 1 } else if requested_cpus > 0 { cpus.min(requested_cpus as usize) } else { cpus }.min(files.len());
    if !silent {
        println!("Processing {} files... ", files.len());
        if !run_in_band { println!("Spawning {} workers...", workers); }
        if bool_option(&parsed.options, "dry") { println!("Running in dry mode, no files will be written! "); }
    }

    let root = match root_dir() { Ok(root) => root, Err(error) => { eprintln!("{}", error); std::process::exit(1); } };
    let events = event_file();
    let options_json = format!("{{{}}}", parsed.options.iter().map(|(key, value)| format!("{}:{}", quote(key), value.json())).collect::<Vec<_>>().join(","));
    let request = format!("{{\"transform\":{},\"babel\":{},\"files\":[{}],\"options\":{},\"events\":{}}}", quote(&transform), bool_option(&parsed.options, "babel"), files.iter().map(|file| quote(file)).collect::<Vec<_>>().join(","), options_json, quote(&events.to_string_lossy()));
    let started = Instant::now();
    let status = Command::new("node")
        .arg(root.join("bridge/transform-host.js"))
        .stdin(Stdio::piped())
        .stdout(Stdio::inherit())
        .stderr(Stdio::inherit())
        .spawn()
        .and_then(|mut child| {
            child.stdin.as_mut().expect("piped stdin").write_all(request.as_bytes())?;
            child.wait()
        });

    let mut counts = BTreeMap::from([("error", 0usize), ("nochange", 0usize), ("ok", 0usize), ("skip", 0usize)]);
    let mut stats = BTreeMap::<String, i64>::new();
    let verbose = number_option(&parsed.options, "verbose");
    if let Ok(contents) = fs::read_to_string(&events) {
        for line in contents.lines() {
            if line == "complete" { continue; }
            if line == "error" { *counts.get_mut("error").unwrap() += 1; continue; }
            let fields = line.split('\t').map(decode_base64).collect::<Vec<_>>();
            if fields.len() != 4 { continue; }
            match fields[0].as_str() {
                "status" => {
                    let status = &fields[1];
                    let message = &fields[3];
                    if let Some(count) = counts.get_mut(status.as_str()) { *count += 1; }
                    let show = match status.as_str() { "ok" => verbose >= 2, "nochange" | "skip" => verbose >= 1, "error" => true, _ => false };
